import{_ as p,c as e,o as t,ah as r}from"./chunks/framework.Dnh4IO1K.js";const d=JSON.parse('{"title":"64、【未济】 坎下离上","description":"周易阐真 - 64、【未济】 坎下离上","frontmatter":{"title":"64、【未济】 坎下离上","description":"周易阐真 - 64、【未济】 坎下离上"},"headers":[],"relativePath":"zh/classics/chanzhen/065.md","filePath":"zh/classics/chanzhen/065.md"}'),s={name:"zh/classics/chanzhen/065.md"};function n(c,a,i,o,h,l){return t(),e("div",null,[...a[0]||(a[0]=[r('<blockquote><p>彖曰：未济亨，柔得中也。小狐汔济，未出中也。濡其尾，无攸利，不续终也。虽不当位，刚柔应也。</p></blockquote><h1 id="_64、【未济】-坎下离上" tabindex="-1">64、【未济】 坎下离上 <a class="header-anchor" href="#_64、【未济】-坎下离上" aria-label="Permalink to “64、【未济】 坎下离上”">​</a></h1><p>初六：濡其尾，吝。</p><p>九二：曳其轮，贞吉。</p><p>六三：未济，征凶，利涉大川。</p><p>九四：贞吉，悔亡。震用伐鬼方，三年有赏于大国。</p><p>六五：贞吉，无悔。君子之光，有孚，吉。</p><p>上九：有孚于饮酒，无咎。濡其首，有孚，失是。</p><h2 id="孔易阐真-​" tabindex="-1">孔易阐真 ​ <a class="header-anchor" href="#孔易阐真-​" aria-label="Permalink to “孔易阐真 ​”">​</a></h2><p>大象：火在水上，未济。君子以慎辨物居方。</p><p>未济者，事犹未至于济也。上离火，下坎水，是火在水上也。火在水上，火不能烹水，水不能制火，水火异处，未济之象也。</p><p>君子有见于此，知人一交后天，真者昧而假者出，身心不定，精神昏浊，躁性发而欲念生，以苦为乐，无所不至，不济极矣。然圣人有后天中返先天之道，特人未思其济耳。若欲其济，即能济之。以是慎辨物居方焉。物者，先天后天阴阳真假之物；方者，先天后天阴阳真假所居之方。慎辨物之真假，必须了然于心，真知灼见，毫无一点疑惑而后已。此格物致知之功也。于物之真假，使其各居其方，真者真而假者假，两不相混，此正心诚意之学也。既辨物而明乎理，又居方而不行险，阴阳不杂，真假各别，未济中即有济；亦如水流湿，火就燥，各济其所济，彼此不同途也。盖先天阴阳，所以成真身，后天阴阳，所以成幻身，当其未济，先天后天阴阳相杂，真假相混。能辨其真假，则知先天有先天之方，后天有后天之方，判然分别，不得以后天之物误认为先天之物，强求其济也。慎辨二字，大有深意。辨之须要无微不入，无几不研，不得稍有些子放过。特以先天后天，所争者毫发之间，这边是先天，那边是后天，易于错认。惟谨慎而细辨之，才能认得真切，才能知的各有其方。知的各有其方，即能使各居其方。能使各居其方，则先天可保，后天不发，未济即能济，颠倒之间，真阴真阳相合，水火相交，圣胎有象。圣人以未济卦序于终者，盖欲人于未济之时穷究实理，急求其济耳。噫!“乌龟天上走，朱雀地下飞”，这个哑迷诀，几人悟精微？</p><h2 id="悟元子注解-​" tabindex="-1">悟元子注解 ​ <a class="header-anchor" href="#悟元子注解-​" aria-label="Permalink to “悟元子注解 ​”">​</a></h2><p>汔，音肸。</p><p>未济者，阴阳犹未济也。卦德下坎陷，上离明，明于外而暗于内，因明致陷，因险生明，阴差阳错，两不相应，故谓未济。此炼己退阴，待时返阳之卦，承上小过而来。小过者，动止如一，以小养修无为之道，乃阴阳相济以后之事。当其未济，必先炼去一切陷阳之阴，而后真阴现象，真阳来还，阴阳相济，金丹凝结，此炼己待时，有为之功，所以贵也。</p><p>人自二八数足，乾坤相交，乾中之阳入于坤宫，坤实成坎；坤中之阴入于乾宫，乾虚成离。离中一阴，受乾阳之气，阴阳团聚而变为火；坎中一阳，受坤阴之气，阴阳熏蒸而变为水。此水此火，在后天中阴阳相杂，真假相混，日生夜长。温和之火，化而为暴燥之火；真一之水，化而为淫欲之水。火性一发，识神用事，元神退位；水性一动，浊精作祸，元精消耗。于是争名夺利，比胜好强，损人利己，聪明外用矣；恣情纵欲，迷于声色，自暴自弃，阴险在内矣。</p><p>明用于外而暗于内，陷其真而认其假，人心惟危，道心惟微，性乱命摇，阴阳不和，五行相伤，七情六欲，般般俱全，千谋百智，件件皆有，此未济之所以为未济也。</p><p>然曰未济，是未至于济，非绝不能济，特人未求其济耳。若求其济，亦终能济，是以未济而有亨道也。未济虽有亨道，但后天阴气用事已久，先天真阳陷溺已深，未能遽然有济，必须炼己之功，方能见效。炼己者，炼人心也。人心为群阴之祖，人心一去，群阴亦化，虚室生白，真阳渐有可复之几。但未到炼己纯熟之时，则心不虚而明不真，阴气犹未退尽，不可急求其济，倘不知火候，急欲济之，是人心用事，假明做作，未济终不济，如小狐汔济，濡其尾，无攸利矣。狐属阴，多疑之物，小狐虽疑少，不能无疑。人心不去，道心不彰，亦小狐之类，虽有济之几，未至济之时。几于济而炼己未熟，虽欲向前，反成落后，濡尾不利，如何能济?故修道者，炼己必至于虚极静笃，陷阳之阴退尽，方能先天至阳之气，自虚无中来，真阴真阳，两而合一，未济者而能济。经云：“炼己不熟，还丹不结。”可知炼己为修真第一着。炼已待时，岂小补云哉!</p><p>初六，在深险之处，为下德之人。修道须先炼己持心，由渐而顿，未可遽求其济。乃愚而自用，亦欲效高明者之致济，身未动而险即随之，如濡其尾而不能前，适以取吝而已。此未济而强求其济者也。</p><p>九二，刚以柔用，大智若愚，大巧若拙，炼己待时，如车曳其轮，暂时养刚，虽在未济之时，而有暗济之吉。此未济而待时致济者也。</p><p>六三，在未济之极，将有可济之几，不知药物火候，依一己之阴，妄想有济，行险侥幸，未济终不济，征远而未有不凶者。幸其居于二阳之间，能顺有道之士，借人济己，阴可化而阳可复，虽涉大川之险，亦吉无不利矣。此未济而求师致济者也。</p><p>九四，刚居柔位，似乎失正，不吉而致悔。然其所以贞吉而悔可亡者，特以勇猛精进，用刚道震起，伐鬼方而除后天之阴；潜修密炼，用柔道，三年有赏于大国，以复先天之阳。然必三年有赏者，真阳为假阴所陷已久，真者固不易复，假者亦所难除，必须功深日远，方能有济。此未济而渐次致济者也。</p><p>六五，虚人心而求道心，不为假明所误，是以贞吉也。下应二阳，取彼坎中之实，以填我离中之虚，虚心而能实腹，是以无悔也。贞吉，无悔，阴阳相合，假明去而真明生。寂然不动，感而遂通，感而遂通，寂然不动。是谓君子之光，始而未济者，终而大济，其致吉已于虚心信之矣。此未济而能虚心致济者也。</p><p>上九，在未济之终，正是有济之时，可信其阴阳相济，出于自然，不待勉强，饮酒宴乐，可以无咎。然天时虽有济，亦人事不可废。尽人事以扶天道，则天人合发，信于济而信之是矣。否则天时有济，不过偶然间耳。若无调理水火之功，则先天至宝，来而又去，济之不固，终归不济，如濡其首，有孚失是矣。此乘时而用人力致济者也。</p><p>然则未济致济之道，当阳气有陷，须炼己待时以防险；及阳气出陷，又当借明破暗以化阴。急缓进退，不失其时，方是阴阳相济、性命双修之道。学者欲修大道，可不以炼己为先哉!</p>',25)])])}const m=p(s,[["render",n]]);export{d as __pageData,m as default};
